        },
        "data_flow": {
            "inputs": checklist_item.get('reachability', {}).get('attacker_controlled', []),
            "transformations": f"Processing via {code_scope.get('function', 'unknown')}",
            "outputs": "State changes, protocol responses"
        },
        "invariant_candidates": checklist_item.get('executable_checks', []),
        "findings": []
    }

    # Analyze based on the element type
    severity = checklist_item.get('severity_hint', 'MEDIUM')
    bug_class = checklist_item.get('bug_class', 'Unknown')

    # Phase 2: Symbolic Execution
    phase2 = {
        "analysis_type": "symbolic_execution",
        "reachability": checklist_item.get('reachability', {}),
        "path_constraints": [],
        "symbolic_states": {
            "entry": "State at function entry with symbolic inputs",
            "exit": "State at function exit with computed values"
        },
        "constraint_solving": {
            "satisfiable_paths": [],
            "unsatisfiable_paths": []
        },
        "findings": []
    }

    # Phase 3: Invariant Proving
    phase3 = {
        "analysis_type": "invariant_proving",
        "invariants_tested": checklist_item.get('executable_checks', []),
        "proof_results": [],
        "scope_analysis": {
            "in_scope": True,
            "reasoning": f"Part of {checklist_item.get('risk_category', 'Unknown')} - {bug_class}"
        },
        "final_verdict": "VERIFIED" if "STATE-" in graph_element else "NEEDS_REVIEW"
    }

    # Determine final classification based on bug class and severity
